<?php
 namespace Pterodactyl\Models\Dezerx; use Pterodactyl\Models\User; use Pterodactyl\Models\ApiKey; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; class DiscordBotMember extends Model { protected $table = 'dezerx_discord_bot_members'; protected $guarded = ['id']; protected $casts = [ 'user_id' => 'int', 'api_key_id' => 'int', ]; public function user(): BelongsTo { return $this->belongsTo(User::class, 'user_id'); } public function apiKey(): BelongsTo { return $this->belongsTo(ApiKey::class, 'api_key_id'); } public function avatarUrl(): string { if ($this->avatar === null || $this->avatar === '') { return 'https://cdn.discordapp.com/embed/avatars/' . ((int) substr($this->discord_id, -1) % 5) . '.png'; } return sprintf('https://cdn.discordapp.com/avatars/%s/%s.png?size=128', $this->discord_id, $this->avatar); } } 